import React from 'react';
import './HomePage.css';
import UpMenu from './UpMenu/UpMenu';
import LeftMenu from './LeftMenu/LeftMenu';
import UserStatus from './TheFeed/UserStatus';
import RightMenu from './RightMenu/RightMenu';
import Posts from './TheFeed/Posts';
import { useState } from 'react';
import { createContext } from 'react';
import { useEffect } from 'react';


export const ThemeContext = createContext(null);


function HomePage({ activeUser,setActiveUser }) {
    const [postsList, setPostsList] = useState([]);
    const [usersList, setUsersList] = useState([]);
    const [theme, setTheme] = useState("light");

    //yaaronet this is what i changed:)
    useEffect(() => {
        // Call the getPosts function when the component is mounted
        getPosts();
        getUsers();
    
    }, []);

    const getUsers = async () => {
        const response = await fetch('http://localhost:8080/api/users', {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${activeUser.token}`
        },
        });
        const data = await response.json();
        setUsersList(data);
        
    }

    const getPosts = async () => {
        const response = await fetch('http://localhost:8080/api/posts', {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${activeUser.token}`
        },
        
        });
        const data = await response.json();
        const sortData = [...data].sort((a, b) => new Date(b.date) - new Date(a.date));
        setPostsList(sortData);
        console.log(postsList);
    }

    const changeTheme = () => {
        setTheme((curr) => { return curr === "light" ? "dark" : "light"; });
    };




    return (
        <ThemeContext.Provider value={{theme, changeTheme}}>
        <div className="container- fluid" id={theme}>
            <div className="row upfeed">

                <UpMenu activeUser={activeUser} changeTheme = {changeTheme} setActiveUser={setActiveUser} postsList={postsList} setPostsList={setPostsList}/>
            </div>
            <div className="row feed">
                <div className="col-3">
                    <LeftMenu activeUser={activeUser}
                              correnttheme={theme}/>

                </div>
                <div className="row col-6">
                    <UserStatus
                        activeUser={activeUser}
                        setPostsList={setPostsList}
                        postsList={postsList} />
                        {postsList.map((post) =>
                        <Posts {...post}
                            activeUser={activeUser}
                            postsList={postsList}
                            setPostsList={setPostsList}
                            correnttheme={theme}
                            key={post._id} />
                    )}
                </div>
                <div className="col-3">
                    <RightMenu />
                </div>
            </div>
        </div>
        </ThemeContext.Provider>
    );
}

export default HomePage;
